		p1:stopSound(k)
	end

	for k, v in pairs(p1.connections) do
		if typeof(v) == "RBXScriptConnection" then
			v:Disconnect()

			continue
		end

		if typeof(v) == "thread" then
			task.cancel(v)
		end
	end

	for k, v in pairs(p1.soundPools) do
		v:Destroy()
	end

	p1.activeSounds = {}
	p1.soundPools = {}
	p1.connectedTracks = {}
	p1.connections = {}
end

return t